import{_t as e,it as t,n,rt as r}from"./chunks/framework.CzJE1L4g.js";var i=JSON.parse(`{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"PvZ-Portable · Mod Development","text":"From a first mod to rewriting the game with Mixin and the content API","tagline":"For mod authors of the PvZ-Portable Java port — the same chapters in English and Chinese","actions":[{"theme":"brand","text":"Getting started","link":"/en/guide/index"},{"theme":"alt","text":"API reference","link":"/en/guide/reference"}]},"features":[{"title":"1. Getting started","details":"Prerequisites, running the game, where the mods/ directory is, and a first mod that runs"},{"title":"2. Project structure","details":"The pvz-content-mod layout, both build scripts, every fabric.mod.json field, and the meaning of run/"},{"title":"3. Mixin experiments","details":"Picking a target, the mixin config, complete copyable @Inject/@Redirect/@ModifyConstant/@Accessor examples, and require"},{"title":"4. Content with fabric-api","details":"Registering plants and zombies, overriding existing numbers, images and reanimations, resource overrides, events"},{"title":"5. Walkthrough","details":"pvz-content-mod file by file — registration, the art pipeline, seed-packet drawing, unlock gates"},{"title":"6. Building, testing, publishing","details":"build/test/runClient, how an end-to-end test is written, publishToMavenLocal, handing the jar to a player"},{"title":"7. API reference","details":"The public API of every module, and where to read the real implementations"}]},"headers":[],"relativePath":"en/index.md","filePath":"en/index.md"}`),a={name:`en/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="what-this-documentation-is" tabindex="-1">What this documentation is <a class="header-anchor" href="#what-this-documentation-is" aria-label="Permalink to “What this documentation is”">​</a></h2><p>This site is about one thing: <strong>writing mods for PvZ-Portable</strong>. PvZ-Portable is a Java desktop port of <em>Plants vs. Zombies</em> GOTY (JDK 25 + Gradle + LWJGL/SDL3) that <strong>runs on the real Fabric Loader</strong>, so a mod is an ordinary Fabric mod: a <code>fabric.mod.json</code>, a <code>ModInitializer</code> entry point and a jar.</p><p>The chapters run from &quot;nothing&quot; to &quot;the game behaves differently&quot;:</p><table tabindex="0"><thead><tr><th>Chapter</th><th>Read it to</th></tr></thead><tbody><tr><td><a href="./guide/">1. Getting started</a></td><td>Prepare the environment and the game, and let a first mod run</td></tr><tr><td><a href="./guide/structure.html">2. Project structure</a></td><td>Understand every file of a mod project, and what the toolchain does for you</td></tr><tr><td><a href="./guide/mixin.html">3. Mixin experiments</a></td><td>Rewrite game classes without touching the game&#39;s source, with a complete example</td></tr><tr><td><a href="./guide/content.html">4. Plants and zombies</a></td><td>Register content and override existing numbers with <code>api-plant</code> / <code>api-zombie</code></td></tr><tr><td><a href="./guide/resources.html">5. Resources and art</a></td><td>Images, reanimations, and loose files above the pak</td></tr><tr><td><a href="./guide/events.html">6. Events and lifecycle</a></td><td>Observe the game with <code>api-events</code>, and when not to</td></tr><tr><td><a href="./guide/content-mod.html">7. Walkthrough</a></td><td><code>pvz-content-mod</code> file by file: how three red plants come to exist</td></tr><tr><td><a href="./guide/build.html">8. Building, testing, publishing</a></td><td>Build, test, publish and ship a mod</td></tr><tr><td><a href="./guide/reference.html">9. API reference</a></td><td>Look up a class or a method</td></tr></tbody></table><p>The Chinese version lives at the site root and mirrors these chapters one to one.</p><h2 id="what-actually-exists-in-the-workspace" tabindex="-1">What actually exists in the workspace <a class="header-anchor" href="#what-actually-exists-in-the-workspace" aria-label="Permalink to “What actually exists in the workspace”">​</a></h2><p>Every snippet in this documentation comes from a real project of the workspace, so it can be read and run as it stands:</p><table tabindex="0"><thead><tr><th>Project</th><th>What it is</th></tr></thead><tbody><tr><td><code>PvZ-Portable/</code></td><td>The game itself (mod id <code>pvz-portable</code>), <strong>not</strong> a mod</td></tr><tr><td><code>fabric-api/</code></td><td>The mod API: <code>api-base</code>, <code>api-events</code>, <code>api-plant</code>, <code>api-resource</code>, <code>api-zombie</code>; the aggregate coordinate is <code>cn.enaium.fabricpvz:fabric-api</code></td></tr><tr><td><code>loom/</code></td><td>The toolchain Gradle plugin <code>cn.enaium.fabricpvz.loom</code>: one plugin line brings the game and the libraries its version package&#39;s manifest names (Loader, Mixin, ASM, the logging stack, LWJGL), <code>runClient</code> and jar-in-jar</td></tr><tr><td><code>pvz-example-mod/</code></td><td>The smallest runnable example: events plus three mixins</td></tr><tr><td><code>pvz-content-mod/</code></td><td>The teaching example: three red plants, registration, an art pipeline and an end-to-end test</td></tr><tr><td><code>pvz-mod-95-edition/</code></td><td>A large rebalance example: rule and number overrides, written in Kotlin</td></tr></tbody></table><p>Every project in the table can be opened next to this site; the build scripts and snippets here follow their current contents. The toolchain supplies only the game and the libraries its version package&#39;s manifest names; Kotlin, JUnit, <code>fabric-language-kotlin</code> and the API are declared by each mod itself.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};